"use client";

import {
  type TransitionPresentation,
  TransitionSeries,
} from "@remotion/transitions";
import type { ReactNode } from "react";
import { AbsoluteFill, interpolate, useCurrentFrame } from "remotion";
import { DynamicGrid } from "@/components/snap-cn/dynamic-grid";
import { planTransitionTiming } from "./duration";
import { FeatureFrame } from "./feature-frame";
import {
  CtaScene,
  cameraCraneUp,
  EASE_OUT,
  FONT,
  PRODUCT_DEMO_DARK_THEME,
  PRODUCT_DEMO_LIGHT_THEME,
  type ProductDemoConfig,
  type ProductDemoScene,
  resolveTiming,
  spatialPush,
  type TemplateTheme,
  zoomThrough,
} from "./foundation";
import { ProductHero } from "./product-hero";

export {
  CTA_SETTLE_FRAMES,
  ctaHoldFrames,
  getProductDemoDuration,
} from "./duration";
export type {
  ProductDemoConfig,
  ProductDemoScene,
  TemplateTheme,
} from "./foundation";
export {
  PRODUCT_DEMO_DARK_THEME,
  PRODUCT_DEMO_LIGHT_THEME,
} from "./foundation";

export type BackgroundMode = "dynamic-grid" | "solid";

export interface A1ProductDemoProps {
  /** Hero headline — the product name. */
  productName?: string;
  /** One-line pitch under the hero name. */
  pitch?: string;
  featureOneTitle?: string;
  featureOneBullet?: string;
  featureTwoTitle?: string;
  featureTwoBullet?: string;
  /** End-card headline. */
  ctaLine?: string;
  /** End-card domain, rendered in the accent color. */
  ctaDomain?: string;
  accentColor?: string;
  background?: BackgroundMode;
  theme?: "light" | "dark";
  speed?: number;
  /** Full scene config. When provided, the content props above are ignored. */
  config?: ProductDemoConfig;
}

const THEME_TOKENS: Record<"light" | "dark", TemplateTheme> = {
  light: PRODUCT_DEMO_LIGHT_THEME,
  dark: PRODUCT_DEMO_DARK_THEME,
};

export const DEFAULT_PRODUCT_DEMO_CONFIG: ProductDemoConfig = {
  meta: { fps: 30, width: 1920, height: 1080 },
  theme: PRODUCT_DEMO_DARK_THEME,
  scenes: [
    {
      type: "product-hero",
      durationInFrames: 120,
      content: {
        name: "Acme Analytics",
        pitch: "Know your numbers",
      },
    },
    {
      type: "feature-frame",
      durationInFrames: 150,
      content: {
        title: "Dashboards",
        bullet: "Every metric on one live canvas — no queries, no waiting",
        side: "left",
        art: "chart",
      },
    },
    {
      type: "feature-frame",
      durationInFrames: 150,
      content: {
        title: "Alerts",
        bullet: "Get pinged the moment a number moves out of range",
        side: "right",
        art: "list",
      },
    },
    {
      type: "cta-scene",
      durationInFrames: 120,
      content: { line: "Start free", domain: "acme.dev" },
    },
  ],
};

type ScenePresentation = TransitionPresentation<Record<string, unknown>>;

function planPresentation(
  from: ProductDemoScene,
  to: ProductDemoScene,
): ScenePresentation {
  if (from.type === "feature-frame" && to.type === "feature-frame") {
    const direction = to.content.side === "right" ? "left" : "right";
    return spatialPush({ direction }) as unknown as ScenePresentation;
  }
  if (from.type === "feature-frame" && to.type === "cta-scene") {
    return zoomThrough() as unknown as ScenePresentation;
  }
  return cameraCraneUp() as unknown as ScenePresentation;
}

function SceneBackground({
  scene,
  theme,
  background,
}: {
  scene: ProductDemoScene;
  theme: TemplateTheme;
  background: BackgroundMode;
}) {
  const grid =
    background === "dynamic-grid" &&
    (scene.type === "product-hero" || scene.type === "cta-scene");

  if (grid) {
    return (
      <AbsoluteFill>
        <DynamicGrid
          cellSize={56}
          background={theme.background}
          lineColor={`${theme.foreground}0d`}
          direction="diagonal"
        />
      </AbsoluteFill>
    );
  }

  return <AbsoluteFill style={{ background: theme.background }} />;
}

// ---------------------------------------------------------------------------
// Snapshot artwork (skeleton UI inside the feature cards)
// ---------------------------------------------------------------------------

const SNAPSHOT_START = 18;
const SNAPSHOT_STAGGER = 4;

function SnapshotLine({
  width,
  strong,
  order,
  theme,
  f,
}: {
  width: string;
  strong?: boolean;
  order: number;
  theme: TemplateTheme;
  f: number;
}) {
  const start = SNAPSHOT_START + order * SNAPSHOT_STAGGER;
  return (
    <div
      style={{
        height: 16,
        width,
        borderRadius: 6,
        background: strong ? `${theme.foreground}30` : `${theme.foreground}16`,
        opacity: interpolate(f, [start, start + 12], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        }),
        scale: `${interpolate(f, [start, start + 12], [0.6, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        })} 1`,
        transformOrigin: "left center",
      }}
    />
  );
}

function PanelSnapshot({
  theme,
  speed = 1,
}: {
  theme: TemplateTheme;
  speed?: number;
}) {
  const f = useCurrentFrame() * speed;
  const sidebar: Array<[string, boolean?]> = [
    ["70%", true],
    ["90%"],
    ["80%"],
    ["60%"],
    ["85%"],
  ];
  const main: Array<[string, boolean?]> = [
    ["40%", true],
    ["100%"],
    ["95%"],
    ["88%"],
    ["70%"],
  ];

  return (
    <div style={{ display: "flex", gap: 22, height: "100%" }}>
      <div
        style={{
          flex: "0 0 30%",
          display: "flex",
          flexDirection: "column",
          gap: 16,
          paddingRight: 22,
          borderRight: `1px solid ${theme.border ?? `${theme.foreground}14`}`,
        }}
      >
        {sidebar.map(([width, strong], i) => (
          <SnapshotLine
            // biome-ignore lint/suspicious/noArrayIndexKey: skeleton rows are positional and never reorder
            key={`s-${i}`}
            width={width}
            strong={strong}
            order={i}
            theme={theme}
            f={f}
          />
        ))}
      </div>
      <div
        style={{ flex: 1, display: "flex", flexDirection: "column", gap: 18 }}
      >
        {main.map(([width, strong], i) => (
          <SnapshotLine
            // biome-ignore lint/suspicious/noArrayIndexKey: skeleton rows are positional and never reorder
            key={`m-${i}`}
            width={width}
            strong={strong}
            order={i + 2}
            theme={theme}
            f={f}
          />
        ))}
      </div>
    </div>
  );
}

const CHART_BARS = [42, 58, 38, 72, 55, 88];

function ChartSnapshot({
  theme,
  speed = 1,
}: {
  theme: TemplateTheme;
  speed?: number;
}) {
  const f = useCurrentFrame() * speed;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100%",
        gap: 20,
      }}
    >
      <SnapshotLine width="34%" strong order={0} theme={theme} f={f} />
      <div
        style={{
          flex: 1,
          display: "flex",
          alignItems: "flex-end",
          gap: 22,
          paddingBottom: 2,
          borderBottom: `1px solid ${theme.border ?? `${theme.foreground}14`}`,
        }}
      >
        {CHART_BARS.map((height, i) => {
          const start = SNAPSHOT_START + i * SNAPSHOT_STAGGER;
          const last = i === CHART_BARS.length - 1;
          return (
            <div
              // biome-ignore lint/suspicious/noArrayIndexKey: chart bars are positional and never reorder
              key={`bar-${i}`}
              style={{
                flex: 1,
                height: `${height}%`,
                borderRadius: "8px 8px 0 0",
                background: last ? theme.accent : `${theme.foreground}1c`,
                scale: `1 ${interpolate(f, [start, start + 16], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: EASE_OUT,
                })}`,
                transformOrigin: "bottom center",
              }}
            />
          );
        })}
      </div>
      <SnapshotLine width="52%" order={7} theme={theme} f={f} />
    </div>
  );
}

const ALERT_ROWS: Array<{ width: string; hot?: boolean }> = [
  { width: "72%" },
  { width: "58%", hot: true },
  { width: "80%" },
  { width: "64%" },
];

function ListSnapshot({
  theme,
  speed = 1,
}: {
  theme: TemplateTheme;
  speed?: number;
}) {
  const f = useCurrentFrame() * speed;

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        gap: 18,
        height: "100%",
      }}
    >
      {ALERT_ROWS.map(({ width, hot }, i) => {
        const start = SNAPSHOT_START + i * (SNAPSHOT_STAGGER + 2);
        return (
          <div
            // biome-ignore lint/suspicious/noArrayIndexKey: alert rows are positional and never reorder
            key={`row-${i}`}
            style={{
              display: "flex",
              alignItems: "center",
              gap: 16,
              padding: "20px 22px",
              borderRadius: 10,
              border: `1px solid ${
                hot
                  ? `${theme.accent}66`
                  : (theme.border ?? `${theme.foreground}14`)
              }`,
              background: hot ? `${theme.accent}14` : "transparent",
              opacity: interpolate(f, [start, start + 14], [0, 1], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: EASE_OUT,
              }),
              translate: `0px ${interpolate(f, [start, start + 14], [14, 0], {
                extrapolateLeft: "clamp",
                extrapolateRight: "clamp",
                easing: EASE_OUT,
              })}px`,
            }}
          >
            <span
              style={{
                width: 12,
                height: 12,
                borderRadius: "50%",
                background: hot ? theme.accent : `${theme.foreground}2a`,
              }}
            />
            <span
              style={{
                height: 14,
                width,
                borderRadius: 6,
                background: hot
                  ? `${theme.foreground}30`
                  : `${theme.foreground}16`,
              }}
            />
          </div>
        );
      })}
    </div>
  );
}

function SnapshotArt({
  art,
  theme,
  speed,
}: {
  art: "panel" | "chart" | "list";
  theme: TemplateTheme;
  speed: number;
}) {
  if (art === "chart") {
    return <ChartSnapshot theme={theme} speed={speed} />;
  }
  if (art === "list") {
    return <ListSnapshot theme={theme} speed={speed} />;
  }
  return <PanelSnapshot theme={theme} speed={speed} />;
}

// ---------------------------------------------------------------------------
// Template
// ---------------------------------------------------------------------------

export function ProductDemo({
  config,
  background = "dynamic-grid",
  speed = 1,
}: {
  config: ProductDemoConfig;
  background?: BackgroundMode;
  speed?: number;
}) {
  const { theme, scenes } = config;

  const nodes: ReactNode[] = [];
  scenes.forEach((scene, index) => {
    nodes.push(
      <TransitionSeries.Sequence
        // biome-ignore lint/suspicious/noArrayIndexKey: scenes are positional and never reorder
        key={`scene-${index}`}
        durationInFrames={scene.durationInFrames}
      >
        <SceneBackground scene={scene} theme={theme} background={background} />
        <SceneContent scene={scene} theme={theme} speed={speed} />
      </TransitionSeries.Sequence>,
    );

    const next = scenes[index + 1];
    if (next) {
      nodes.push(
        <TransitionSeries.Transition
          // biome-ignore lint/suspicious/noArrayIndexKey: transitions are positional and never reorder
          key={`transition-${index}`}
          presentation={planPresentation(scene, next)}
          timing={resolveTiming(planTransitionTiming(scene, next))}
        />,
      );
    }
  });

  return (
    <AbsoluteFill
      style={{
        background: theme.background,
        fontFamily: theme.fontFamily ?? FONT,
      }}
    >
      <TransitionSeries>{nodes}</TransitionSeries>
    </AbsoluteFill>
  );
}

function SceneContent({
  scene,
  theme,
  speed,
}: {
  scene: ProductDemoScene;
  theme: TemplateTheme;
  speed: number;
}) {
  if (scene.type === "product-hero") {
    return <ProductHero content={scene.content} theme={theme} speed={speed} />;
  }
  if (scene.type === "feature-frame") {
    return (
      <FeatureFrame
        title={scene.content.title}
        bullet={scene.content.bullet}
        side={scene.content.side}
        accent={theme.accent}
        theme={theme}
        header=""
        frame={
          <SnapshotArt
            art={scene.content.art ?? "panel"}
            theme={theme}
            speed={speed}
          />
        }
        speed={speed}
      />
    );
  }
  return (
    <CtaScene
      line={scene.content.line}
      domain={scene.content.domain}
      theme={theme}
      speed={speed}
    />
  );
}

export function A1ProductDemo({
  productName,
  pitch,
  featureOneTitle,
  featureOneBullet,
  featureTwoTitle,
  featureTwoBullet,
  ctaLine,
  ctaDomain,
  accentColor,
  background = "dynamic-grid",
  theme = "dark",
  speed = 1,
  config,
}: A1ProductDemoProps) {
  const base = config ?? {
    ...DEFAULT_PRODUCT_DEMO_CONFIG,
    scenes: DEFAULT_PRODUCT_DEMO_CONFIG.scenes.map((scene) => {
      if (scene.type === "product-hero") {
        return {
          ...scene,
          content: {
            ...scene.content,
            name: productName ?? scene.content.name,
            pitch: pitch ?? scene.content.pitch,
          },
        };
      }
      if (scene.type === "feature-frame") {
        const first = scene.content.side === "left";
        return {
          ...scene,
          content: {
            ...scene.content,
            title:
              (first ? featureOneTitle : featureTwoTitle) ??
              scene.content.title,
            bullet:
              (first ? featureOneBullet : featureTwoBullet) ??
              scene.content.bullet,
          },
        };
      }
      return {
        ...scene,
        content: {
          ...scene.content,
          line: ctaLine ?? scene.content.line,
          domain: ctaDomain ?? scene.content.domain,
        },
      };
    }),
  };

  const tokens = THEME_TOKENS[theme];
  const resolvedConfig: ProductDemoConfig = {
    ...base,
    theme: {
      ...tokens,
      accent: accentColor ?? tokens.accent,
      fontFamily: base.theme.fontFamily ?? tokens.fontFamily,
    },
  };

  return (
    <ProductDemo
      config={resolvedConfig}
      background={background}
      speed={speed}
    />
  );
}

"use client";

import {
  linearTiming,
  springTiming,
  type TransitionPresentation,
  type TransitionPresentationComponentProps,
} from "@remotion/transitions";
import type { FC, ReactNode } from "react";
import { AbsoluteFill, Easing, interpolate, useCurrentFrame } from "remotion";
import { CTA_SETTLE_FRAMES, type SceneTiming } from "./duration";

export type { SceneTiming } from "./duration";

export interface TemplateMeta {
  fps: number;
  width: number;
  height: number;
}

export interface TemplateTheme {
  accent: string;
  background: string;
  foreground: string;
  muted: string;
  /** Card / panel fill. Falls back to transparent when omitted. */
  surface?: string;
  /** Hairline border color. Falls back to a foreground alpha when omitted. */
  border?: string;
  fontFamily?: string;
}

export interface ProductHeroContent {
  name: string;
  pitch: string;
  entrance?: "kinetic-center-build" | "per-character-rise";
}

export interface FeatureFrameContent {
  title: string;
  bullet: string;
  side: "left" | "right";
  /** Which skeleton artwork the snapshot card renders. */
  art?: "panel" | "chart" | "list";
}

export interface CtaContent {
  line: string;
  domain: string;
}

export type ProductDemoScene =
  | {
      type: "product-hero";
      durationInFrames: number;
      content: ProductHeroContent;
    }
  | {
      type: "feature-frame";
      durationInFrames: number;
      content: FeatureFrameContent;
    }
  | { type: "cta-scene"; durationInFrames: number; content: CtaContent };

export interface ProductDemoConfig {
  meta: TemplateMeta;
  theme: TemplateTheme;
  scenes: ProductDemoScene[];
}

/** Inter-like sans stack used across the template. */
export const FONT =
  "Inter, 'Inter Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif";

/** Fast, subtle ease-out — the template's default motion curve. */
export const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
export const CAMERA_TRAVEL_EASE = Easing.out(Easing.cubic);

/** First-class light theme: #FAFAFA canvas, #FFFFFF surfaces, #E4E7EC hairlines. */
export const PRODUCT_DEMO_LIGHT_THEME: TemplateTheme = {
  accent: "#266DF0",
  background: "#FAFAFA",
  surface: "#FFFFFF",
  border: "#E4E7EC",
  foreground: "#101828",
  muted: "#667085",
  fontFamily: FONT,
};

export const PRODUCT_DEMO_DARK_THEME: TemplateTheme = {
  accent: "#266DF0",
  background: "#0A0A0B",
  surface: "#141417",
  border: "#26272B",
  foreground: "#FAFAFA",
  muted: "#A1A1AA",
  fontFamily: FONT,
};

export function resolveTiming(timing: SceneTiming) {
  return timing.kind === "spring"
    ? springTiming({
        durationInFrames: timing.durationInFrames,
        // High damping: settles without bounce.
        config: { damping: 200 },
      })
    : linearTiming({ durationInFrames: timing.durationInFrames });
}

export interface CameraProps {
  x?: number;
  y?: number;
  scale?: number;
  blur?: number;
  children: ReactNode;
}

export function Camera({
  x = 0,
  y = 0,
  scale = 1,
  blur = 0,
  children,
}: CameraProps) {
  return (
    <AbsoluteFill
      style={{
        translate: `${x}px ${y}px`,
        scale: String(scale),
        transformOrigin: "center",
        filter: blur > 0.01 ? `blur(${blur}px)` : undefined,
        willChange: "transform, filter",
      }}
    >
      {children}
    </AbsoluteFill>
  );
}

// ---------------------------------------------------------------------------
// Scene-transition variants
// ---------------------------------------------------------------------------

type CameraCraneUpProps = Record<string, never>;

const CameraCraneUpPresentation: FC<
  TransitionPresentationComponentProps<CameraCraneUpProps>
> = ({ children, presentationProgress, presentationDirection }) => {
  const p = presentationProgress;

  return (
    <AbsoluteFill
      style={{
        translate: `0px ${
          presentationDirection === "exiting" ? -p * 100 : (1 - p) * 100
        }%`,
        filter: `blur(${interpolate(p, [0, 0.5, 1], [0, 6, 0])}px)`,
        willChange: "transform, filter",
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

/** Vertical crane move: the outgoing scene lifts away as the next rises in. */
export function cameraCraneUp(): TransitionPresentation<CameraCraneUpProps> {
  return { component: CameraCraneUpPresentation, props: {} };
}

type SpatialPushProps = { direction: "up" | "down" | "left" | "right" };

const SpatialPushPresentation: FC<
  TransitionPresentationComponentProps<SpatialPushProps>
> = ({
  children,
  presentationProgress,
  presentationDirection,
  passedProps,
}) => {
  const p = presentationProgress;
  const { direction } = passedProps;

  if (presentationDirection === "exiting") {
    return (
      <AbsoluteFill
        style={{
          scale: String(interpolate(p, [0, 1], [1, 0.94])),
          filter: `brightness(${interpolate(p, [0, 1], [1, 0.72])}) blur(${interpolate(p, [0, 0.5, 1], [0, 4, 0])}px)`,
          willChange: "transform, filter",
        }}
      >
        {children}
      </AbsoluteFill>
    );
  }

  const horizontal = direction === "left" || direction === "right";
  const sign = direction === "up" || direction === "left" ? 1 : -1;
  const offset = sign * (1 - p) * 100;

  return (
    <AbsoluteFill
      style={{
        translate: horizontal ? `${offset}% 0px` : `0px ${offset}%`,
        filter: `blur(${interpolate(p, [0, 0.5, 1], [0, 4, 0])}px)`,
        willChange: "transform, filter",
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

/** Lateral push: the incoming feature slides over the receding one. */
export function spatialPush(
  props: SpatialPushProps,
): TransitionPresentation<SpatialPushProps> {
  return { component: SpatialPushPresentation, props };
}

type ZoomThroughProps = Record<string, never>;

const ZoomThroughPresentation: FC<
  TransitionPresentationComponentProps<ZoomThroughProps>
> = ({ children, presentationProgress, presentationDirection }) => {
  const p = presentationProgress;

  if (presentationDirection === "exiting") {
    return (
      <AbsoluteFill
        style={{
          scale: String(interpolate(p, [0, 1], [1, 1.12])),
          opacity: interpolate(p, [0, 0.85], [1, 0], {
            extrapolateRight: "clamp",
          }),
          filter: `blur(${interpolate(p, [0, 1], [0, 8])}px)`,
          willChange: "transform, filter, opacity",
        }}
      >
        {children}
      </AbsoluteFill>
    );
  }

  return (
    <AbsoluteFill
      style={{
        scale: String(interpolate(p, [0, 1], [0.96, 1])),
        opacity: interpolate(p, [0.15, 1], [0, 1], {
          extrapolateLeft: "clamp",
        }),
        willChange: "transform, opacity",
      }}
    >
      {children}
    </AbsoluteFill>
  );
};

/** Zoom-through into the end card: the last feature dissolves forward. */
export function zoomThrough(): TransitionPresentation<ZoomThroughProps> {
  return { component: ZoomThroughPresentation, props: {} };
}

// ---------------------------------------------------------------------------
// Text entrances
// ---------------------------------------------------------------------------

export interface BlurInTextProps {
  text: string;
  color: string;
  fontSize: number;
  fontWeight?: number;
  fontFamily?: string;
  delay?: number;
  speed?: number;
}

/** Soft blur-in: opacity + blur + a small rise, fast ease-out. */
export function BlurInText({
  text,
  color,
  fontSize,
  fontWeight = 500,
  fontFamily = FONT,
  delay = 0,
  speed = 1,
}: BlurInTextProps) {
  const f = useCurrentFrame() * speed - delay;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      <span
        style={{
          fontSize,
          fontWeight,
          fontFamily,
          color,
          letterSpacing: "-0.01em",
          opacity: interpolate(f, [0, 18], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: EASE_OUT,
          }),
          translate: `0px ${interpolate(f, [0, 18], [14, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: EASE_OUT,
          })}px`,
          filter: `blur(${interpolate(f, [0, 18], [8, 0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: EASE_OUT,
          })}px)`,
        }}
      >
        {text}
      </span>
    </div>
  );
}

export interface MaskRiseTextProps {
  text: string;
  color: string;
  fontSize: number;
  fontWeight?: number;
  fontFamily?: string;
  delay?: number;
  speed?: number;
}

/** Mask reveal: the line rises out of an overflow-hidden strip, no bounce. */
export function MaskRiseText({
  text,
  color,
  fontSize,
  fontWeight = 600,
  fontFamily = FONT,
  delay = 0,
  speed = 1,
}: MaskRiseTextProps) {
  const f = useCurrentFrame() * speed - delay;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <span
        style={{
          fontSize,
          fontWeight,
          fontFamily,
          color,
          letterSpacing: "-0.02em",
          lineHeight: 1.1,
