}

import type { ProductDemoConfig, ProductDemoScene } from "./foundation";

export type SceneTiming = {
  kind: "spring" | "linear";
  durationInFrames: number;
};

/**
 * End-card hold rule: every CTA animation must settle by this frame.
 * Everything after is a static hold, so the outro can be trimmed or
 * looped at any point.
 */
export const CTA_SETTLE_FRAMES = 45;

/** Frames the settled end card holds for a given CTA scene duration. */
export function ctaHoldFrames(sceneDurationInFrames: number): number {
  return Math.max(0, sceneDurationInFrames - CTA_SETTLE_FRAMES);
}

/**
 * Picks the transition length + curve for each scene pair. Short,
 * high-damping moves — no bounce anywhere in the chrome.
 */
export function planTransitionTiming(
  from: ProductDemoScene,
  to: ProductDemoScene,
): SceneTiming {
  if (from.type === "product-hero" && to.type === "feature-frame") {
    return { kind: "spring", durationInFrames: 18 };
  }
  if (from.type === "feature-frame" && to.type === "feature-frame") {
    return { kind: "linear", durationInFrames: 14 };
  }
  if (from.type === "feature-frame" && to.type === "cta-scene") {
    return { kind: "spring", durationInFrames: 16 };
  }
  return { kind: "spring", durationInFrames: 14 };
}

export function getProductDemoDuration(config: ProductDemoConfig): number {
  const total = config.scenes.reduce(
    (sum, scene) => sum + scene.durationInFrames,
    0,
  );
  let overlap = 0;
  for (let i = 0; i < config.scenes.length - 1; i++) {
    overlap += planTransitionTiming(
      config.scenes[i],
      config.scenes[i + 1],
    ).durationInFrames;
  }
  return total - overlap;
}

"use client";

import { AbsoluteFill, interpolate, Sequence, useCurrentFrame } from "remotion";
import type { ProductHeroContent, TemplateTheme } from "./foundation";
import { BlurInText, CAMERA_TRAVEL_EASE, Camera, FONT } from "./foundation";

export interface ProductHeroProps {
  content: ProductHeroContent;
  theme: TemplateTheme;
  speed?: number;
}

const PITCH_DELAY = 28;
const TRAVEL = 16;

export function ProductHero({ content, theme, speed = 1 }: ProductHeroProps) {
  const f = useCurrentFrame() * speed;
  const vertical = content.entrance === "per-character-rise";

  const travel = interpolate(f, [0, TRAVEL], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: CAMERA_TRAVEL_EASE,
  });
  const scale = interpolate(travel, [0, 1], [6.5, 1]);
  const pan = interpolate(travel, [0, 1], [120, 0]);
  const blur = interpolate(f, [0, 10, TRAVEL], [16, 6, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill>
      <Camera
        scale={scale}
        x={vertical ? 0 : -pan}
        y={vertical ? pan : 0}
        blur={blur}
      >
        <AbsoluteFill
          style={{ alignItems: "center", justifyContent: "center" }}
        >
          <span
            style={{
              fontSize: 128,
              fontWeight: 600,
              color: theme.foreground,
              letterSpacing: "-0.02em",
              fontFamily: theme.fontFamily ?? FONT,
            }}
          >
            {content.name}
          </span>
        </AbsoluteFill>
      </Camera>

      <Sequence from={PITCH_DELAY} layout="none">
        <AbsoluteFill
          style={{
            alignItems: "center",
            justifyContent: "center",
            paddingTop: 200,
          }}
        >
          <div style={{ position: "relative", width: "100%", height: 56 }}>
            <BlurInText
              text={content.pitch}
              color={theme.muted}
              fontSize={34}
              fontWeight={500}
              fontFamily={theme.fontFamily ?? FONT}
              speed={speed}
            />
          </div>
        </AbsoluteFill>
      </Sequence>
    </AbsoluteFill>
  );
}

