export function FeatureFrame({
  title,
  bullet,
  side,
  frame,
  accent,
  theme,
  header,
  speed = 1,
}: FeatureFrameProps) {
  const f = useCurrentFrame() * speed;

  const card = (
    <div
      style={{
        flex: "0 0 46%",
        display: "flex",
        opacity: interpolate(f, [0, 20], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        }),
        translate: `${interpolate(f, [0, 20], [side === "left" ? -24 : 24, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        })}px 0px`,
        scale: String(
          interpolate(f, [0, 20], [0.97, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: EASE_OUT,
          }),
        ),
      }}
    >
      <UiSnapshotCard
        header={header}
        borderColor={theme.border ?? `${theme.foreground}1f`}
