function TitleBlock({
  title,
  accent,
  color,
  f,
}: {
  title: string;
  accent: string;
  color: string;
  f: number;
}) {
  const words = title.split(" ");
  const stagger = 4;

  return (
    <div style={{ position: "relative", display: "inline-block" }}>
      <h2
        style={{
          margin: 0,
          fontSize: 64,
          fontWeight: 600,
          lineHeight: 1.05,
          letterSpacing: "-0.02em",
          color,
        }}
      >
        {words.map((word, i) => {
          const local = f - i * stagger;
          return (
            <span
              // biome-ignore lint/suspicious/noArrayIndexKey: words are positional and never reorder
              key={`${word}-${i}`}
              style={{
                display: "inline-block",
                marginRight: "0.26em",
                opacity: interpolate(local, [0, 14], [0, 1], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: EASE_OUT,
                }),
                translate: `0px ${interpolate(local, [0, 14], [22, 0], {
                  extrapolateLeft: "clamp",
                  extrapolateRight: "clamp",
                  easing: EASE_OUT,
                })}px`,
              }}
            >
              {word}
            </span>
          );
        })}
      </h2>
      <span
        style={{
          position: "absolute",
          left: 0,
          bottom: -10,
          height: 5,
          width: "44%",
          borderRadius: 3,
          background: accent,
          transformOrigin: "left center",
          scale: `${interpolate(f, [20, 40], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: EASE_OUT,
          })} 1`,
        }}
      />
    </div>
  );
}

function BulletLine({
  bullet,
  color,
  f,
}: {
  bullet: string;
  color: string;
  f: number;
}) {
  return (
    <p
      style={{
        margin: 0,
        fontSize: 30,
        fontWeight: 400,
        lineHeight: 1.4,
        letterSpacing: "-0.01em",
        color,
        opacity: interpolate(f, [16, 34], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        }),
        translate: `0px ${interpolate(f, [16, 34], [18, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: EASE_OUT,
        })}px`,
      }}
    >
      {bullet}
    </p>
  );
}

