import type { CSSProperties, ReactNode } from "react";

export interface UiSnapshotCardProps {
  header?: string;
  children: ReactNode;
  radius?: number;
  borderColor?: string;
  /** Card fill. Defaults to a white surface per the light-first system. */
  surface?: string;
  /** Window dots + header label color. */
  mutedColor?: string;
  style?: CSSProperties;
}

export function UiSnapshotCard({
  header,
  children,
  radius = 14,
  borderColor = "#E4E7EC",
  surface = "transparent",
  mutedColor = "#667085",
  style,
}: UiSnapshotCardProps) {
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        borderRadius: radius,
        border: `1px solid ${borderColor}`,
        background: surface,
        ...style,
      }}
    >
      {header !== undefined ? (
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 8,
            padding: "14px 18px",
            borderBottom: `1px solid ${borderColor}`,
          }}
        >
          <span style={dotStyle(mutedColor)} />
          <span style={dotStyle(mutedColor)} />
          <span style={dotStyle(mutedColor)} />
          {header.length > 0 ? (
            <span
              style={{
                marginLeft: 12,
                fontSize: 15,
                fontWeight: 500,
                color: mutedColor,
                letterSpacing: "-0.01em",
                fontFamily:
                  "Inter, 'Inter Variable', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif",
