            </span>
          ) : null}
        </div>
      ) : null}
      <div style={{ position: "relative", flex: 1, padding: 22 }}>
        {children}
      </div>
    </div>
  );
}

function dotStyle(color: string): CSSProperties {
  return {
    width: 11,
    height: 11,
    borderRadius: "50%",
    background: color,
    opacity: 0.45,
  };
}
